  function handleInteraction(){if(inPlinko){if(!plinkoBall&&Math.hypot(player.x-600,player.y-145)<115){plinkoBall={x:600,y:170,result:Math.random()<.05};showToast({name:'The puck drops through the wall',color:'#ffd85a'})}else if(!plinkoBall)showToast({name:'Stand at the top of the Plinko wall and press E',color:'#ffd85a'});return}if(inBasement){let lever=basementLevers.find(b=>Math.hypot(player.x-b.x,player.y-b.y)<70);if(lever){let i=basementLevers.indexOf(lever);basementLeversOn[i]=!basementLeversOn[i];save();showToast({name:`Lever ${lever.label} ${basementLeversOn[i]?'ON':'OFF'}`,color:basementLeversOn[i]?'#9ff2d8':'#71809a'});return}return}if(inOcean||inFactory||inIce||inAbyss||currentBiome().id!=='swamp')return;let beacon=swampBeacons.find((b,i)=>!swampActivated[i]&&Math.hypot(player.x-b.x,player.y-b.y)<70);if(beacon){let i=swampBeacons.indexOf(beacon);swampActivated[i]=true;setSwampSquareVisibility();save();showToast({name:`Will-o-wisp beacon ${beacon.label} awakened (${swampActivated.filter(Boolean).length}/3)`,color:'#d5ff8b'})}}
  function drawPlayer(){if(!inOcean&&!inFactory&&!inIce&&!inAbyss&&!inBasement&&!inPlinko){if(Date.now()>dot.next){let candidate;do{candidate={x:80+Math.random()*(W-160),y:110+Math.random()*(H-220)}}while(colliders.some(c=>c.r?Math.hypot(candidate.x-c.x,candidate.y-c.y)<c.r+65:candidate.x>c.x-65&&candidate.x<c.x+c.w+65&&candidate.y>c.y-65&&candidate.y<c.y+c.h+65));dot={...candidate,next:Date.now()+10000}}let x=screenX(dot.x),y=screenY(dot.y);ctx.fillStyle='#ffd85a';ctx.beginPath();ctx.arc(x,y,9,0,7);ctx.fill();ctx.strokeStyle='#fff5b0';ctx.lineWidth=3;ctx.stroke();if(Math.hypot(player.x-dot.x,player.y-dot.y)<30){inPlinko=true;player.x=600;player.y=150;showToast({name:'The wandering dot opens a Plinko Chamber',color:'#ffd85a'})}}if(inPlinko){player.x=Math.max(70,Math.min(1130,player.x));player.y=Math.max(65,Math.min(1110,player.y));if(player.x<130&&player.y>1030){inPlinko=false;player.x=dot.x+55;player.y=dot.y;showToast({name:'You return to the mainland',color:'#ffd85a'})}}if(inPlinko&&plinkoBall){plinkoBall.y+=13;plinkoBall.x+=(plinkoBall.result?600:360+Math.floor(Math.random()*5)*120-plinkoBall.x)*.08;if(plinkoBall.y>970){let prize=squares.find(s=>s.name==='Plinko Square');if(plinkoBall.result){found[prize.id]=new Date().toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'});save();updateUI();showToast(prize)}else showToast({name:'The puck lands in a white hole — try again',color:'#f7f7ff'});plinkoBall=null}}if(inBasement){let solved=!basementLeversOn[0]&&basementLeversOn[1]&&!basementLeversOn[2]&&basementLeversOn[3],cx=screenX(760),cy=screenY(570);ctx.fillStyle='#171826';ctx.fillRect(cx-76,cy+52,152,26);ctx.fillStyle='#f7d8f1';ctx.font='900 12px Nunito';ctx.textAlign='center';ctx.fillText(solved?'CABINET OPEN':'CABINET LOCKED',cx,cy+70);basementLevers.forEach(b=>{ctx.fillStyle='#d9e4ee';ctx.font='900 11px Nunito';ctx.fillText('PRESS E',screenX(b.x),screenY(b.y+72))})}if(!miniMap.hidden)drawActiveMap()}
