  function voidTick(){let now=Date.now(),mainWorld=!inOcean&&!inFactory&&!inIce&&!inAbyss&&!inBasement&&!inPlinko&&!inMoon&&!inMoonBase&&!inVoid;if(mainWorld&&!blackHole.active&&now>=blackHole.next){blackHole={active:true,x:160+Math.random()*(W-320),y:160+Math.random()*(H-320),expires:now+5000,next:now+55000}}if(blackHole.active&&now>=blackHole.expires)blackHole.active=false;if(mainWorld&&blackHole.active&&Math.hypot(player.x-blackHole.x,player.y-blackHole.y)<48){inVoid=true;player.x=voidHub.x+115;player.y=voidHub.y;blackHole.active=false;showToast({name:'The black hole tears open a path to the Void',color:'#c79cff'})}if(inVoid){player.x=Math.max(35,Math.min(VOID_W-35,player.x));player.y=Math.max(35,Math.min(VOID_H-35,player.y));if(Math.hypot(player.x-voidExit.x,player.y-voidExit.y)<voidExit.r){inVoid=false;player.x=330;player.y=900;showToast({name:'You escape the Void',color:'#c79cff'})}voidTeleporters.forEach(p=>{if(now>voidTeleCooldown&&Math.hypot(player.x-p.x,player.y-p.y)<36){let destinations=[{x:520,y:350},{x:850,y:850},{x:1270,y:310},{x:1520,y:760},{x:1900,y:1120}];let d=destinations[Math.floor(Math.random()*destinations.length)];player.x=d.x;player.y=d.y;voidTeleCooldown=now+1600;showToast({name:'The Void warps you somewhere else',color:'#c79cff'})}});voidShardLocations.forEach((p,i)=>{if(!voidShards[i]&&Math.hypot(player.x-p.x,player.y-p.y)<34){voidShards[i]=true;save();showToast({name:`Corrupted shard found (${voidShards.filter(Boolean).length}/10)`,color:'#ff5ee2'});if(voidShards.every(Boolean)){let corrupt=squares.find(s=>s.name==='Corrupted Square');corrupt.x=player.x+70;corrupt.y=player.y;showToast({name:'All shards resonate — Corrupted Square appears beside you',color:'#ff5ee2'})}}})}requestAnimationFrame(voidTick)}requestAnimationFrame(voidTick);
